<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole('passenger');$pdo=$db->getConnection();$uid=$auth->getUserId();$u=$auth->getUserInfo();$stmt=$pdo->prepare("SELECT COUNT(*) total,SUM(status NOT IN ('claimed','lost')) active,SUM(status='lost') lost FROM baggage WHERE passenger_id=?");$stmt->execute([$uid]);$s=$stmt->fetch()?:['total'=>0,'active'=>0,'lost'=>0];$stmt=$pdo->prepare("SELECT b.baggage_code,b.status,b.weight,f.flight_number,f.departure_time FROM baggage b JOIN flights f ON b.flight_id=f.id WHERE b.passenger_id=? ORDER BY b.created_at DESC LIMIT 8");$stmt->execute([$uid]);$bags=$stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Passenger Dashboard</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-primary"><div class="container"><span class="navbar-brand">Smart Baggage</span><span class="text-white"><?=htmlspecialchars($u['full_name']??'Passenger')?> · <a class="text-white" href="../includes/logout.php">Logout</a></span></div></nav><div class="container py-4"><h2>Passenger Dashboard</h2><div class="row g-3 my-2"><div class="col-md-4"><div class="card"><div class="card-body"><h6>Total baggage</h6><div class="fs-2"><?=intval($s['total']??0)?></div></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><h6>Active</h6><div class="fs-2"><?=intval($s['active']??0)?></div></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><h6>Lost</h6><div class="fs-2"><?=intval($s['lost']??0)?></div></div></div></div></div><div class="mb-3"><a class="btn btn-primary" href="baggage_tracking.php">Track baggage</a> <a class="btn btn-outline-primary" href="flight_info.php">Flight info</a> <a class="btn btn-outline-secondary" href="history.php">History</a> <a class="btn btn-outline-secondary" href="../pages/profile.php">Profile</a></div><div class="card"><div class="card-header">Recent baggage</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Code</th><th>Flight</th><th>Status</th><th>Weight</th><th></th></tr></thead><tbody><?php foreach($bags as $b):?><tr><td><?=htmlspecialchars($b['baggage_code'])?></td><td><?=htmlspecialchars($b['flight_number'])?></td><td><?=htmlspecialchars($b['status'])?></td><td><?=htmlspecialchars($b['weight'])?></td><td><a href="baggage_tracking.php?code=<?=urlencode($b['baggage_code'])?>">Track</a></td></tr><?php endforeach;?></tbody></table></div></div></di